insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('adab3c87-b87c-4333-be47-0ae627a47c67','61e0de73-8206-4bf9-8ed7-f4132de7db50',1,1,'AZ ERDŐ EGY PILLANATRA ELHALLGAT','Márk és Lili egy falevelekkel teli ösvényen halad. Márk a lehullott levelekre lépked: roppanás, roppanás, szünet. Lili a föld mellé hajló páfrányt kerülgeti. Nem egyforma ritmusban járnak. Márk megáll, hogy bevárja.
Márk még egy levelet keres. Egy különösen nagyot szemel ki. Mire rálépne, a levél felemelkedik, és egy vékony türkiz fénycsík suhan el alatta.
A fény a gyökerek között villan. Lili füle fordul, követi az irányát. A madárhangok egy pillanatra elcsendesednek. Márk lehajol; a fény már nincs ott. Mögöttük újra felvillan. Három rövid fény, aztán sötét.
Egy lapos kő mögött derengés jelenik meg. Márk odalép, de Lili eléteszi a mancsát.
A kamera a kőre közelít: az alatta megbújó, csillag alakú apró szilánk fényt vet a levelek erezetére.
A szilánk egy tiszta, üveges hangot ad.','Márk és Lili egy falevelekkel teli ösvényen halad. Márk a lehullott levelekre lépked: roppanás, roppanás, szünet. Lili a föld mellé hajló páfrányt kerülgeti. Nem egyforma ritmusban járnak. Márk megáll, hogy bevárja.
Márk még egy levelet keres. Egy különösen nagyot szemel ki. Mire rálépne, a levél felemelkedik, és egy vékony türkiz fénycsík suhan el alatta.
A fény a gyökerek között villan. Lili füle fordul, követi az irányát. A madárhangok egy pillanatra elcsendesednek. Márk lehajol; a fény már nincs ott. Mögöttük újra felvillan. Három rövid fény, aztán sötét.
Egy lapos kő mögött derengés jelenik meg. Márk odalép, de Lili eléteszi a mancsát.
A kamera a kőre közelít: az alatta megbújó, csillag alakú apró szilánk fényt vet a levelek erezetére.
A szilánk egy tiszta, üveges hangot ad.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
