insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('b0d01e4a-b5d1-5a5c-899d-3c80e82b8865','61e0de73-8206-4bf9-8ed7-f4132de7db50','adab3c87-b87c-4333-be47-0ae627a47c67','cec97482-1a11-4861-a09c-ad12c95476c5',6,6,'Nem fut el. Mintha jelezne.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
