insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('5256a635-9df7-59d9-bb7f-dfade79ca7a4','61e0de73-8206-4bf9-8ed7-f4132de7db50',2,2,'FŐCÍM','A csillag fénye a Csodakapu kőbe vésett jelébe úszik át. WONDERLY TALES / CSODAKAPU. Rövid saját főcímzene. A felirat után vissza ugyanarra a kőre; nincs történeti időugrás vagy idegen világból bevágott előrejelzés.','A csillag fénye a Csodakapu kőbe vésett jelébe úszik át. WONDERLY TALES / CSODAKAPU. Rövid saját főcímzene. A felirat után vissza ugyanarra a kőre; nincs történeti időugrás vagy idegen világból bevágott előrejelzés.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('a046176b-d3fe-55f2-9988-eacc502abe67','61e0de73-8206-4bf9-8ed7-f4132de7db50',3,3,'EGY DARAB CSILLAG','Márk a hátizsákból összehajtott kendőt vesz elő. A kő mellett guggol. Lili megvizsgálja a talajt: nincs égés, nincs füst, a moha ép.
Márk a kendőre emeli a szilánkot. A kézmozdulat lassú, mindkét tenyér látszik. A szilánk eleinte halvány; amikor az ösvény régi tisztás felőli részére fordulnak, erősebb lesz.
Lili megkerüli Márkot. A fiú vele együtt fordul, a fény csökken.
A fény erősödik.
Márk a szilánk peremét figyeli. A csillag egyik oldala szabályos, a másik törött, nem éles; a törésben halvány kék szál fut.
Márk elindulna a derengés felé. Megáll, Lilit nézi.
Lili elmosolyodik, bólint. A fiú letakarja a szilánkot a kendő egyik szélével. A fény átdereng. Együtt követik az ösvényt. A fény rövid időre megvilágít egy régi, kőbe vésett körjelet a gyökerek alatt. Lili megjegyzi a formáját.','Márk a hátizsákból összehajtott kendőt vesz elő. A kő mellett guggol. Lili megvizsgálja a talajt: nincs égés, nincs füst, a moha ép.
Márk a kendőre emeli a szilánkot. A kézmozdulat lassú, mindkét tenyér látszik. A szilánk eleinte halvány; amikor az ösvény régi tisztás felőli részére fordulnak, erősebb lesz.
Lili megkerüli Márkot. A fiú vele együtt fordul, a fény csökken.
A fény erősödik.
Márk a szilánk peremét figyeli. A csillag egyik oldala szabályos, a másik törött, nem éles; a törésben halvány kék szál fut.
Márk elindulna a derengés felé. Megáll, Lilit nézi.
Lili elmosolyodik, bólint. A fiú letakarja a szilánkot a kendő egyik szélével. A fény átdereng. Együtt követik az ösvényt. A fény rövid időre megvilágít egy régi, kőbe vésett körjelet a gyökerek alatt. Lili megjegyzi a formáját.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('225ebeac-c6fb-5641-a488-fede3eb27b90','61e0de73-8206-4bf9-8ed7-f4132de7db50','a046176b-d3fe-55f2-9988-eacc502abe67','cec97482-1a11-4861-a09c-ad12c95476c5',1,1,'Nem forró. A moha nem száradt ki körülötte.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
