insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('d1511295-d1f5-529c-b534-8b393bee23b7','61e0de73-8206-4bf9-8ed7-f4132de7db50','a046176b-d3fe-55f2-9988-eacc502abe67','cec97482-1a11-4861-a09c-ad12c95476c5',5,5,'Fordulj vissza egy kicsit.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
