insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('25db74df-0d73-592f-82d8-642847187bac','61e0de73-8206-4bf9-8ed7-f4132de7db50','a046176b-d3fe-55f2-9988-eacc502abe67','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',10,10,'Előbb nézzük meg?','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('9d364d4d-35a7-5146-bf5f-572b0e245d0a','61e0de73-8206-4bf9-8ed7-f4132de7db50',4,4,'MAKKFALVA BARÁTAI','Morzsi kosárral, Pötty kulaccsal érkezik. Bogyó előttük szaglászik. Zizi egy guruló kis szerkezetet húz; az egyik kerék mindig más irányba akar menni.
Bogyó megszagolja a kendőt, halk vakkantással hátralép, aztán kíváncsian előre. Pötty óvatosan belenéz.
Zizi a szilánk fölé tartja az eszközét. A mutató egyszer jobbra, egyszer balra ugrik, majd a hátuljára fordul.
Zizi visszafordítja. A mutató a régi tisztásra mutat.
Lili megmutatja a fény változását. Zizi kikapcsolja a gépét, hogy ne zavarja a halk csilingelést.
Bogyó két rövid ugatással körbeszaladja őket. Pötty megsimítja a füle tövét.
A csapat elindul. Zizi felveszi a szerkezetet, ne akadjon a gyökerekbe.','Morzsi kosárral, Pötty kulaccsal érkezik. Bogyó előttük szaglászik. Zizi egy guruló kis szerkezetet húz; az egyik kerék mindig más irányba akar menni.
Bogyó megszagolja a kendőt, halk vakkantással hátralép, aztán kíváncsian előre. Pötty óvatosan belenéz.
Zizi a szilánk fölé tartja az eszközét. A mutató egyszer jobbra, egyszer balra ugrik, majd a hátuljára fordul.
Zizi visszafordítja. A mutató a régi tisztásra mutat.
Lili megmutatja a fény változását. Zizi kikapcsolja a gépét, hogy ne zavarja a halk csilingelést.
Bogyó két rövid ugatással körbeszaladja őket. Pötty megsimítja a füle tövét.
A csapat elindul. Zizi felveszi a szerkezetet, ne akadjon a gyökerekbe.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
