insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('b21ab5f7-c8d6-5378-a9a4-e5bb316c2866','61e0de73-8206-4bf9-8ed7-f4132de7db50','9d364d4d-35a7-5146-bf5f-572b0e245d0a','7786acf1-e358-4afd-9c7e-448230ada56e',6,6,'A világ legelső mindenmérője. Most épp azt méri, hogy…','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('73956111-1041-505c-9c41-f4fe9b53d960','61e0de73-8206-4bf9-8ed7-f4132de7db50','9d364d4d-35a7-5146-bf5f-572b0e245d0a','2eccce5e-599e-42bf-a58e-2068c34b312f',7,7,'Hogy fejjel lefelé van?','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('3511b9ad-52e2-5666-910c-fa9ceb5e4803','61e0de73-8206-4bf9-8ed7-f4132de7db50','9d364d4d-35a7-5146-bf5f-572b0e245d0a','7786acf1-e358-4afd-9c7e-448230ada56e',8,8,'Pontosan. Ezt nagyon pontosan méri.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('971cb9b5-361f-5309-a44b-d87c0d7e1256','61e0de73-8206-4bf9-8ed7-f4132de7db50','9d364d4d-35a7-5146-bf5f-572b0e245d0a','7786acf1-e358-4afd-9c7e-448230ada56e',9,9,'Van benne egy egyszerű iránytű is. Az nem az én találmányom.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('0a415faa-7978-5324-892e-2070fe388496','61e0de73-8206-4bf9-8ed7-f4132de7db50','9d364d4d-35a7-5146-bf5f-572b0e245d0a','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',10,10,'A régi kapuhoz megyünk? Ahhoz, ami sosem nyílik ki?','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('165ae290-a683-5036-a462-cb44fd4c9d9f','61e0de73-8206-4bf9-8ed7-f4132de7db50','9d364d4d-35a7-5146-bf5f-572b0e245d0a','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',11,11,'Csak megnézzük, miért arra világít.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('e2ba4057-2070-539d-abba-804b021f4d92','61e0de73-8206-4bf9-8ed7-f4132de7db50','9d364d4d-35a7-5146-bf5f-572b0e245d0a','2eccce5e-599e-42bf-a58e-2068c34b312f',12,12,'Együtt megyünk. Én viszem a kosarat.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('3ac5a262-fbc1-5a72-89c5-93b37fbefcff','61e0de73-8206-4bf9-8ed7-f4132de7db50','9d364d4d-35a7-5146-bf5f-572b0e245d0a','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',13,13,'Jól van. De ha a kapu köszön, én is köszönök. És aztán gondolkodom.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('963ad53f-5fd0-52cc-bb7e-3fb8f4943dcb','61e0de73-8206-4bf9-8ed7-f4132de7db50',5,5,'A CSODAKAPU FELÉBRED','A kapu mohos, öreg köveket és fény nélküli türkiz hornyokat mutat. Az előtérben lapos kövek. Márk és Lili az elfogadott képre emlékeztető pozícióban, de ténylegesen mozognak. A többiek mögöttük érnek be.
A fény a szilánkból a földön lévő egyik jelre vetül. Fényfolyam fut végig a kövek közti réseken. A kapu három felső jele sorban felragyog. Morzsi maga mellé húzza a kosarat; Pötty megkapaszkodik a kosár fülében.
Semmi válasz. Halk kőrezgés. Zizi nem nyúl a kapuhoz, hanem a felvillanó jeleket rajzolja le egy noteszbe.
A középső üreg nem szilánk alakú, hanem egy teljes csillag körvonala. Márk óvatosan közelebb tartja a kendőt. A kapu belsejében kör alakú fényfelület jelenik meg.
A felületből áttűnik egy másik táj: füves szigetek lebegnek a felhők között. Keskeny fényutak kötik össze őket, a középen lévő torony három arany harangot tart. Egyetlen harang sem mozdul. A levelek ott különösen lassan hullanak.
Bogyó a kapu mellett ül le. A farka megáll. A saját erdőjük madarai tovább énekelnek; a túloldalon szokatlan csend van.','A kapu mohos, öreg köveket és fény nélküli türkiz hornyokat mutat. Az előtérben lapos kövek. Márk és Lili az elfogadott képre emlékeztető pozícióban, de ténylegesen mozognak. A többiek mögöttük érnek be.
A fény a szilánkból a földön lévő egyik jelre vetül. Fényfolyam fut végig a kövek közti réseken. A kapu három felső jele sorban felragyog. Morzsi maga mellé húzza a kosarat; Pötty megkapaszkodik a kosár fülében.
Semmi válasz. Halk kőrezgés. Zizi nem nyúl a kapuhoz, hanem a felvillanó jeleket rajzolja le egy noteszbe.
A középső üreg nem szilánk alakú, hanem egy teljes csillag körvonala. Márk óvatosan közelebb tartja a kendőt. A kapu belsejében kör alakú fényfelület jelenik meg.
A felületből áttűnik egy másik táj: füves szigetek lebegnek a felhők között. Keskeny fényutak kötik össze őket, a középen lévő torony három arany harangot tart. Egyetlen harang sem mozdul. A levelek ott különösen lassan hullanak.
Bogyó a kapu mellett ül le. A farka megáll. A saját erdőjük madarai tovább énekelnek; a túloldalon szokatlan csend van.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('a245e68c-538b-5b61-8afd-9dfe0dcdef90','61e0de73-8206-4bf9-8ed7-f4132de7db50','963ad53f-5fd0-52cc-bb7e-3fb8f4943dcb','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',1,1,'Ugyanolyan, mint mindig.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('a1507187-0bb2-5117-8ce6-feac27ea8b0d','61e0de73-8206-4bf9-8ed7-f4132de7db50','963ad53f-5fd0-52cc-bb7e-3fb8f4943dcb','cec97482-1a11-4861-a09c-ad12c95476c5',2,2,'A szilánk viszont nem.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('f4bf4416-7a04-5e2e-8acb-257f5c8ea78c','61e0de73-8206-4bf9-8ed7-f4132de7db50','963ad53f-5fd0-52cc-bb7e-3fb8f4943dcb','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',3,3,'Jó napot kívánok.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('0f70cefc-a76f-57ee-b88f-d843e0f71a2b','61e0de73-8206-4bf9-8ed7-f4132de7db50','963ad53f-5fd0-52cc-bb7e-3fb8f4943dcb','7786acf1-e358-4afd-9c7e-448230ada56e',4,4,'A fény három helyen áll meg. Utána visszamegy a közepére.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('1da1be2c-df22-5c11-8756-c9a55d466feb','61e0de73-8206-4bf9-8ed7-f4132de7db50','963ad53f-5fd0-52cc-bb7e-3fb8f4943dcb','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',5,5,'Lehet, hogy oda kell tenni.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('feeb63a3-af1f-54c0-88d1-e744fdd66163','61e0de73-8206-4bf9-8ed7-f4132de7db50','963ad53f-5fd0-52cc-bb7e-3fb8f4943dcb','cec97482-1a11-4861-a09c-ad12c95476c5',6,6,'Nem érintetted hozzá.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('53c5f26f-2f3e-5aa5-8782-da57667dfaef','61e0de73-8206-4bf9-8ed7-f4132de7db50','963ad53f-5fd0-52cc-bb7e-3fb8f4943dcb','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',7,7,'Akkor most kivételesen jó, hogy nem érintettem hozzá.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('8901d1fc-e3d1-5cf9-8cdd-18cc230da21a','61e0de73-8206-4bf9-8ed7-f4132de7db50','963ad53f-5fd0-52cc-bb7e-3fb8f4943dcb','2eccce5e-599e-42bf-a58e-2068c34b312f',8,8,'Az ott… az ég?','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('43187395-39a5-5b09-adb3-3b827e3f80bd','61e0de73-8206-4bf9-8ed7-f4132de7db50','963ad53f-5fd0-52cc-bb7e-3fb8f4943dcb','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',9,9,'Remélem, van rajta föld is.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('5c05627c-9300-5543-b355-aba67c5f8556','61e0de73-8206-4bf9-8ed7-f4132de7db50','963ad53f-5fd0-52cc-bb7e-3fb8f4943dcb','cec97482-1a11-4861-a09c-ad12c95476c5',10,10,'Ott valami nem működik.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('5756becf-8eb2-58dc-b0bd-35c373c5ded6','61e0de73-8206-4bf9-8ed7-f4132de7db50',6,6,'EGYÜTT, VISSZAÚTTAL','Márk a kapukerethez lép, és egy leesett levelet átnyújt a fényen. Elengedi. A levél a túloldali fűre esik. Bogyó kíváncsian nyújtaná utána az orrát; Lili visszahívja.
Zizi egy narancsszínű szalagot vesz elő. A túloldalon álló bokor ágára rögzíthetik; a kapukerethez nem kötnek semmit.
Pötty a többieket számolja, Bogyót kétszer is.
Márk és Lili együtt lép át. Szilánk a kendőben, Márk két kezében. A többiek követik. Morzsi hátrafordul: az erdő a kapun belül ugyanott marad. Leteszi a kosarat a fűre. Zizi a közeli bokorra köti a szalagot.
A szigeten kis lapos körkő áll, rajta három lehajtott levélalak. A harmadik levél alól fény villan. A szilánk válaszol.
Lili belenéz a körkő üres közepébe: kerek, sekély vájat, ahonnan mintha hiányozna valami.','Márk a kapukerethez lép, és egy leesett levelet átnyújt a fényen. Elengedi. A levél a túloldali fűre esik. Bogyó kíváncsian nyújtaná utána az orrát; Lili visszahívja.
Zizi egy narancsszínű szalagot vesz elő. A túloldalon álló bokor ágára rögzíthetik; a kapukerethez nem kötnek semmit.
Pötty a többieket számolja, Bogyót kétszer is.
Márk és Lili együtt lép át. Szilánk a kendőben, Márk két kezében. A többiek követik. Morzsi hátrafordul: az erdő a kapun belül ugyanott marad. Leteszi a kosarat a fűre. Zizi a közeli bokorra köti a szalagot.
A szigeten kis lapos körkő áll, rajta három lehajtott levélalak. A harmadik levél alól fény villan. A szilánk válaszol.
Lili belenéz a körkő üres közepébe: kerek, sekély vájat, ahonnan mintha hiányozna valami.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('1c101b7b-c767-523a-be6e-e85916fe0bd2','61e0de73-8206-4bf9-8ed7-f4132de7db50','5756becf-8eb2-58dc-b0bd-35c373c5ded6','cec97482-1a11-4861-a09c-ad12c95476c5',1,1,'Várj, Bogyó. Előbb megbeszéljük.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('12e7c19e-723b-55ac-885d-0f8f33a484b3','61e0de73-8206-4bf9-8ed7-f4132de7db50','5756becf-8eb2-58dc-b0bd-35c373c5ded6','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',2,2,'Menjünk át arra az első szigetre. A kaput végig látjuk. Nem indulunk el egyedül.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('181a5c89-2658-56a3-a39b-86b931d531e4','61e0de73-8206-4bf9-8ed7-f4132de7db50','5756becf-8eb2-58dc-b0bd-35c373c5ded6','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',3,3,'És ha onnan ez a kapu nem látszik?','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('50346244-a4fa-59c0-a5a0-8fabfebdbfcc','61e0de73-8206-4bf9-8ed7-f4132de7db50','5756becf-8eb2-58dc-b0bd-35c373c5ded6','7786acf1-e358-4afd-9c7e-448230ada56e',4,4,'Ezt látni fogjuk. És ha el akarunk menni messzebb, előbb megint megállunk.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('11a1c913-8fec-52e8-b266-f1b5682cc1ff','61e0de73-8206-4bf9-8ed7-f4132de7db50','5756becf-8eb2-58dc-b0bd-35c373c5ded6','2eccce5e-599e-42bf-a58e-2068c34b312f',5,5,'Én leszek az utolsó. Megnézem, hogy mind megvagyunk.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('86fdd780-a61a-5f91-b880-203935fa329e','61e0de73-8206-4bf9-8ed7-f4132de7db50','5756becf-8eb2-58dc-b0bd-35c373c5ded6','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',6,6,'Hat. Azaz hét… Nem. Hat. Bogyó gyors.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('b20e0877-47fd-5ba3-ac43-7aaa1c2c3dea','61e0de73-8206-4bf9-8ed7-f4132de7db50','5756becf-8eb2-58dc-b0bd-35c373c5ded6','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',7,7,'Itt is ugyanaz a jel.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('c04f419e-03c7-53a6-bb13-b9543040fb73','61e0de73-8206-4bf9-8ed7-f4132de7db50','5756becf-8eb2-58dc-b0bd-35c373c5ded6','cec97482-1a11-4861-a09c-ad12c95476c5',8,8,'És itt is hiányzik egy darab.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('a843864a-e287-51ce-93ce-5f5ff06c058f','61e0de73-8206-4bf9-8ed7-f4132de7db50',7,7,'A SZÉLKERT','A csapat nem megy azonnal a toronyhoz. Körülnéznek. A szigetek közti fényhíd a következő füves kis szigetre vezet. Vastag fonott korlátja van. Mögötte a második híd csukva; a fénykövei a földre simulnak.
Zizi megmutat egy megszáradt virágot és egy lecsukott szélkereket. A talajon apró vízcsatorna fut, de a csatornában megállt a víz. Egy felhő a virág fölé ér, két cseppet ejt, majd tovább nem tud mozdulni.
Bogyó megszagolja a hídkorlátot, aztán a körkő felé fordul. A körkő három levéljele három külön színben villan: arany, türkiz, arany. A torony felől egy elakadó haranghang érkezik.
Morzsi játékosan tüsszent egyet. Bogyó felkapja a fejét; a feszültség oldódik.
A csapat átsétál az első hídon. Pötty középen, Morzsi mellette; a nyúl a fonott korláton csúsztatja a kezét. Lili ellenőrzi, hogy a kapu mögöttük látható marad.','A csapat nem megy azonnal a toronyhoz. Körülnéznek. A szigetek közti fényhíd a következő füves kis szigetre vezet. Vastag fonott korlátja van. Mögötte a második híd csukva; a fénykövei a földre simulnak.
Zizi megmutat egy megszáradt virágot és egy lecsukott szélkereket. A talajon apró vízcsatorna fut, de a csatornában megállt a víz. Egy felhő a virág fölé ér, két cseppet ejt, majd tovább nem tud mozdulni.
Bogyó megszagolja a hídkorlátot, aztán a körkő felé fordul. A körkő három levéljele három külön színben villan: arany, türkiz, arany. A torony felől egy elakadó haranghang érkezik.
Morzsi játékosan tüsszent egyet. Bogyó felkapja a fejét; a feszültség oldódik.
A csapat átsétál az első hídon. Pötty középen, Morzsi mellette; a nyúl a fonott korláton csúsztatja a kezét. Lili ellenőrzi, hogy a kapu mögöttük látható marad.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('9c116b9d-be6a-54b8-8b66-40da4b03542d','61e0de73-8206-4bf9-8ed7-f4132de7db50','a843864a-e287-51ce-93ce-5f5ff06c058f','2eccce5e-599e-42bf-a58e-2068c34b312f',1,1,'A fák nem mozognak.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('e7b1a4b0-4761-5cf5-93e0-dbd505ec87f8','61e0de73-8206-4bf9-8ed7-f4132de7db50','a843864a-e287-51ce-93ce-5f5ff06c058f','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',2,2,'Az jó. Akkor nem hajolnak ránk.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('dc000e91-6703-577f-bf9d-35b4c7c8d78c','61e0de73-8206-4bf9-8ed7-f4132de7db50','a843864a-e287-51ce-93ce-5f5ff06c058f','cec97482-1a11-4861-a09c-ad12c95476c5',3,3,'A levelek sem. Pedig azoknak mozogniuk kellene.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('e29fe777-50de-5af5-b5c5-2d6949471507','61e0de73-8206-4bf9-8ed7-f4132de7db50','a843864a-e287-51ce-93ce-5f5ff06c058f','7786acf1-e358-4afd-9c7e-448230ada56e',4,4,'A szélkerék emelné a vizet. Ha nem forog, a virág sem kap eleget.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('914e5854-cdf4-5652-a7d1-2e3e0d2b0f92','61e0de73-8206-4bf9-8ed7-f4132de7db50','a843864a-e287-51ce-93ce-5f5ff06c058f','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',5,5,'Akkor a toronyból kell szelet csinálnunk.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('d4e5157c-0775-537a-bae2-556ba9969460','61e0de73-8206-4bf9-8ed7-f4132de7db50','a843864a-e287-51ce-93ce-5f5ff06c058f','cec97482-1a11-4861-a09c-ad12c95476c5',6,6,'Nézzük meg előbb, miért állt meg.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('5ac5de6c-78b8-53ae-8b1b-ab99b7712446','61e0de73-8206-4bf9-8ed7-f4132de7db50','a843864a-e287-51ce-93ce-5f5ff06c058f','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',7,7,'Olyan, mintha valaki tüsszenteni akarna, csak nem sikerül neki.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('6c6b1ac6-7081-581a-b544-fe117c26ba7e','61e0de73-8206-4bf9-8ed7-f4132de7db50',8,8,'A HÁROM HANG','A csukott második híd mellett három alacsony, levél alakú fújtató áll. Mindegyikhez áttetsző cső tartozik. A csövek a torony harangjai felé mennek. Az első alatt kör, a második alatt két pont, a harmadik alatt hullám jelölés.
Morzsi megnyomja az elsőt. Egy kis légörvény a bajusza alá fúj. A távoli harang mélyen kong. Morzsi szőre felborzolódik.
Pötty megnyomja a másodikat. Magasabb hang szól. Bogyó a harmadikra lépne, de a közös ellenőrzés kedvéért Lili finoman maga mellé hívja.
Márk megnyomja a harmadikat. A középső hang szól; egy fénykő a híd előtt felemelkedik, aztán visszaereszkedik.
A kapusziget körköve most távolról is látszik. Fényjelei ugyanolyan sorrendben pulzálnak. Lili a jeleket figyeli, de Márk már a fújtatók elé áll.
Az első terv gyorsabb, mint a megfigyelés. Pötty tétován hátralép.','A csukott második híd mellett három alacsony, levél alakú fújtató áll. Mindegyikhez áttetsző cső tartozik. A csövek a torony harangjai felé mennek. Az első alatt kör, a második alatt két pont, a harmadik alatt hullám jelölés.
Morzsi megnyomja az elsőt. Egy kis légörvény a bajusza alá fúj. A távoli harang mélyen kong. Morzsi szőre felborzolódik.
Pötty megnyomja a másodikat. Magasabb hang szól. Bogyó a harmadikra lépne, de a közös ellenőrzés kedvéért Lili finoman maga mellé hívja.
Márk megnyomja a harmadikat. A középső hang szól; egy fénykő a híd előtt felemelkedik, aztán visszaereszkedik.
A kapusziget körköve most távolról is látszik. Fényjelei ugyanolyan sorrendben pulzálnak. Lili a jeleket figyeli, de Márk már a fújtatók elé áll.
Az első terv gyorsabb, mint a megfigyelés. Pötty tétován hátralép.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('eea8fcc5-ff88-550b-859a-73e55c01920f','61e0de73-8206-4bf9-8ed7-f4132de7db50','6c6b1ac6-7081-581a-b544-fe117c26ba7e','7786acf1-e358-4afd-9c7e-448230ada56e',1,1,'Nyomásra levegőt küldenek. Csak azt nem tudom még, mennyit.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('abdc8951-fbfe-5612-845d-0754af954d23','61e0de73-8206-4bf9-8ed7-f4132de7db50','6c6b1ac6-7081-581a-b544-fe117c26ba7e','2eccce5e-599e-42bf-a58e-2068c34b312f',2,2,'Ezt a frizurát nem kértem.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('3dc5484a-1823-5628-a624-1cb7c39dd315','61e0de73-8206-4bf9-8ed7-f4132de7db50','6c6b1ac6-7081-581a-b544-fe117c26ba7e','cec97482-1a11-4861-a09c-ad12c95476c5',3,3,'Egyszerre csak egyet. Halljuk, mit csinál.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('9e589d4b-bbd0-589b-957f-e3a29bdf267c','61e0de73-8206-4bf9-8ed7-f4132de7db50','6c6b1ac6-7081-581a-b544-fe117c26ba7e','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',4,4,'Láttátok? Már majdnem megnyílt!','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('d7682d33-cc19-52bf-8215-a0aa73284dfd','61e0de73-8206-4bf9-8ed7-f4132de7db50','6c6b1ac6-7081-581a-b544-fe117c26ba7e','cec97482-1a11-4861-a09c-ad12c95476c5',5,5,'Márk, várj. Szerintem megmutatja…','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('69bda51c-238d-5d36-87ec-70827da6e985','61e0de73-8206-4bf9-8ed7-f4132de7db50','6c6b1ac6-7081-581a-b544-fe117c26ba7e','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',6,6,'Mind a három kell hozzá. Morzsi, ezt nyomd. Zizi, azt!','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('d253ba72-bd7c-5aeb-9472-919fdb5c1935','61e0de73-8206-4bf9-8ed7-f4132de7db50',9,9,'TÚL SOK EGYSZERRE','Márk jelére hárman egyszerre nyomják meg a fújtatókat. A harangok összevissza szólnak. Rövid, erős légpöffenés támad. Csak levelek és a kendő egyik szabad sarka mozdul; senkit nem fúj a szakadékba. Márk két kézzel védi a szilánkot.
A híd fényköve elfordul, a három levéljel elsötétül. Egy kis arany körlap ugrik ki a torony csövének nyitott foglalatából, és a híd melletti, sekély kőhoronyba gurul. A nyílás fedett; a lap elérhető, de a rés szűk. Pötty követi a tekintetével.
Zizi rögtön elengedi a fújtatót. Morzsi is. A szél elül. Bogyó megrázza a füleit, majd odabújik Pöttyhöz.
Lili nem válaszol rögtön. Megnézi, hogy mindenki biztonságban van.
A kapu fénye még látszik, de a három körjel közül kettő egyre halványabb. Nincs visszaszámlálás vagy indokolatlan pánik.
Márk a szilánkot letakarja, a kendőt összehajtva a hátizsák felső zsebébe teszi. Látszik a teljes mozdulat. Kezei szabaddá válnak. A csillag nem kerül önkényesen másik szereplőhöz.','Márk jelére hárman egyszerre nyomják meg a fújtatókat. A harangok összevissza szólnak. Rövid, erős légpöffenés támad. Csak levelek és a kendő egyik szabad sarka mozdul; senkit nem fúj a szakadékba. Márk két kézzel védi a szilánkot.
A híd fényköve elfordul, a három levéljel elsötétül. Egy kis arany körlap ugrik ki a torony csövének nyitott foglalatából, és a híd melletti, sekély kőhoronyba gurul. A nyílás fedett; a lap elérhető, de a rés szűk. Pötty követi a tekintetével.
Zizi rögtön elengedi a fújtatót. Morzsi is. A szél elül. Bogyó megrázza a füleit, majd odabújik Pöttyhöz.
Lili nem válaszol rögtön. Megnézi, hogy mindenki biztonságban van.
A kapu fénye még látszik, de a három körjel közül kettő egyre halványabb. Nincs visszaszámlálás vagy indokolatlan pánik.
Márk a szilánkot letakarja, a kendőt összehajtva a hátizsák felső zsebébe teszi. Látszik a teljes mozdulat. Kezei szabaddá válnak. A csillag nem kerül önkényesen másik szereplőhöz.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('a7993871-29ed-5821-a378-a251bfd6433d','61e0de73-8206-4bf9-8ed7-f4132de7db50','d253ba72-bd7c-5aeb-9472-919fdb5c1935','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',1,1,'Ott állt meg! A cső alatt!','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('210224fd-cf25-5021-b9fd-d80fdcc0b358','61e0de73-8206-4bf9-8ed7-f4132de7db50','d253ba72-bd7c-5aeb-9472-919fdb5c1935','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',2,2,'Elrontottam.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('d6dcb9b5-eb6b-53a2-8992-d575e8eb4010','61e0de73-8206-4bf9-8ed7-f4132de7db50','d253ba72-bd7c-5aeb-9472-919fdb5c1935','cec97482-1a11-4861-a09c-ad12c95476c5',3,3,'Valami elmozdult. Még meg tudjuk nézni.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('a18e0c90-9ac4-59fa-b965-b97b394c5aae','61e0de73-8206-4bf9-8ed7-f4132de7db50','d253ba72-bd7c-5aeb-9472-919fdb5c1935','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',4,4,'Mondtad, hogy várjak.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('6e6fcabe-9017-5cbf-a6ac-851dec1f881d','61e0de73-8206-4bf9-8ed7-f4132de7db50','d253ba72-bd7c-5aeb-9472-919fdb5c1935','cec97482-1a11-4861-a09c-ad12c95476c5',5,5,'Igen. Most megvárunk mindenkit. És kitaláljuk együtt.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('5b59473b-9530-5ad2-bb72-ec157576bbf4','61e0de73-8206-4bf9-8ed7-f4132de7db50','d253ba72-bd7c-5aeb-9472-919fdb5c1935','7786acf1-e358-4afd-9c7e-448230ada56e',6,6,'A körlap nélkül a levegő rossz irányba megy. Úgy, mint amikor lyukas a kulacs.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('981060f2-444a-5e0b-b663-16993c2ce4e5','61e0de73-8206-4bf9-8ed7-f4132de7db50','d253ba72-bd7c-5aeb-9472-919fdb5c1935','2eccce5e-599e-42bf-a58e-2068c34b312f',7,7,'Akkor először visszatesszük a körlapot.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('279cb5d2-f8f0-5791-83cf-eb676349db15','61e0de73-8206-4bf9-8ed7-f4132de7db50',10,10,'BOGYÓ NYOMA','Bogyó a lap fölötti rácsot megszagolja, aztán a cső mellett húzódó keskeny fedett járathoz fut. A járatba egy emberi kar nem fér be, de egy nyúl oldalazva be tud menni. Morzsi óvatosan megtámasztja a meglazult külső fedelet; nem bontanak le terhet tartó építményt.
Pötty leguggol, a belső padlót látja. Megérinti, aztán visszahúzza a kezét.
Zizi egy hosszú pálcát próbál a nyílásba vezetni. A pálca a kanyarban megakad. Nem ismétlik sokszor ugyanazt a kudarcot.
Bogyó halkan nyüszít, a rácson át Pöttyre néz. A nyúl a rácson keresztül a körlapot is meglátja.
Morzsi stabilan tartja a fedelet. Márk a nyílás mellett marad. Zizi leteszi az eszközét, hogy egyik keze se mozgassa meg véletlenül a tartót.
Pötty nagy levegőt vesz. A füleit lehajtja, lassan oldalazva belép. A kamera vele azonos magasságban, a fényes kijáratot is mutatva követi.','Bogyó a lap fölötti rácsot megszagolja, aztán a cső mellett húzódó keskeny fedett járathoz fut. A járatba egy emberi kar nem fér be, de egy nyúl oldalazva be tud menni. Morzsi óvatosan megtámasztja a meglazult külső fedelet; nem bontanak le terhet tartó építményt.
Pötty leguggol, a belső padlót látja. Megérinti, aztán visszahúzza a kezét.
Zizi egy hosszú pálcát próbál a nyílásba vezetni. A pálca a kanyarban megakad. Nem ismétlik sokszor ugyanazt a kudarcot.
Bogyó halkan nyüszít, a rácson át Pöttyre néz. A nyúl a rácson keresztül a körlapot is meglátja.
Morzsi stabilan tartja a fedelet. Márk a nyílás mellett marad. Zizi leteszi az eszközét, hogy egyik keze se mozgassa meg véletlenül a tartót.
Pötty nagy levegőt vesz. A füleit lehajtja, lassan oldalazva belép. A kamera vele azonos magasságban, a fényes kijáratot is mutatva követi.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('3ec452c0-170c-590c-88b1-bf9700ec540f','61e0de73-8206-4bf9-8ed7-f4132de7db50','279cb5d2-f8f0-5791-83cf-eb676349db15','2eccce5e-599e-42bf-a58e-2068c34b312f',1,1,'Itt belül a föld van. Nem az ég fölött megy.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('cec8c9e4-2f95-54f6-bb60-380351ca96d2','61e0de73-8206-4bf9-8ed7-f4132de7db50','279cb5d2-f8f0-5791-83cf-eb676349db15','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',2,2,'Azért elég szűk. És sötét is.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('af93bfbd-b920-51e9-a751-09d3d0b7fa27','61e0de73-8206-4bf9-8ed7-f4132de7db50','279cb5d2-f8f0-5791-83cf-eb676349db15','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',3,3,'Nem kell bemenned. Keressünk más megoldást.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('394e46dd-52c9-5377-ac7a-73908bd76496','61e0de73-8206-4bf9-8ed7-f4132de7db50','279cb5d2-f8f0-5791-83cf-eb676349db15','7786acf1-e358-4afd-9c7e-448230ada56e',4,4,'A kanyar után én nem tudom mozgatni.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('94da9bb5-4069-5b99-868c-f71edb2e1611','61e0de73-8206-4bf9-8ed7-f4132de7db50','279cb5d2-f8f0-5791-83cf-eb676349db15','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',5,5,'Ha bemegyek, a rácsnál látlak benneteket?','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('a2b70aba-09e6-5714-8f69-c4b6c46bb1ae','61e0de73-8206-4bf9-8ed7-f4132de7db50','279cb5d2-f8f0-5791-83cf-eb676349db15','cec97482-1a11-4861-a09c-ad12c95476c5',6,6,'Igen. Itt maradok. Végig beszélünk.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('7ae4ad31-6adb-5462-a61a-3fb5fcc80e99','61e0de73-8206-4bf9-8ed7-f4132de7db50',11,11,'PÖTTY BÁTORSÁGA','Pötty első lépése óvatos. A másodiknál a puha moha megcsiklandozza a talpát; hirtelen megáll.
Pötty megérinti a mohát. Elmosolyodik.
Márk a rács túloldalán megjelenik; nem siettet.
Pötty letérdel. A körlap egy kis mélyedésben van; nem veszélyes szerkezet mellett. A nyúl két kézzel megemeli. Alatta keskeny gyökér nő át egy légnyíláson.
Pötty úgy fordítja a lapot, hogy a kijáraton kiférjen. A füle a falhoz ér; megáll, eligazítja, továbbhalad. Bogyó a kijáratnál hasra fekszik, csóvál.
Kint Morzsi átveszi a lapot, majd elengedi a fedelet, amikor Zizi visszazárta. Pötty leül egy pillanatra a biztos talajra.
Bogyó a nyúl mellé ül, a fejét a vállának dönti. Pötty nevetve megsimogatja. Nincs külön kimondott tanulságmondat vagy hosszú beszéd.
Lili megnézi a körlapot: ugyanaz a három jel van rajta, mint a fújtatóknál.','Pötty első lépése óvatos. A másodiknál a puha moha megcsiklandozza a talpát; hirtelen megáll.
Pötty megérinti a mohát. Elmosolyodik.
Márk a rács túloldalán megjelenik; nem siettet.
