insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('65a30093-c1cc-50c2-9f9e-fa19723df8ef','61e0de73-8206-4bf9-8ed7-f4132de7db50','0b428242-0d70-5691-8458-1e869508544d','7786acf1-e358-4afd-9c7e-448230ada56e',3,3,'A levegő most jó helyre megy. Csak még nem tud kijönni.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('5b1c80f7-57e2-5cd4-ab27-b21999f0577e','61e0de73-8206-4bf9-8ed7-f4132de7db50','0b428242-0d70-5691-8458-1e869508544d','2eccce5e-599e-42bf-a58e-2068c34b312f',4,4,'Akkor megnyitjuk az utat neki.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('56223298-0436-565c-ab61-f6a706247f82','61e0de73-8206-4bf9-8ed7-f4132de7db50','0b428242-0d70-5691-8458-1e869508544d','cec97482-1a11-4861-a09c-ad12c95476c5',5,5,'Együtt maradunk. És nem visszük el a szilánkot, amíg meg nem nézzük, mit tart nyitva.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('4c11a870-0cb6-513f-89b7-8c2911f56517','61e0de73-8206-4bf9-8ed7-f4132de7db50','0b428242-0d70-5691-8458-1e869508544d','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',6,6,'Itt leszünk. Ha változik a fény, szólok.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('9dbf3517-42a6-5b7c-85dd-ceda64f5772a','61e0de73-8206-4bf9-8ed7-f4132de7db50',15,15,'A SZÉLTERELŐ','A terelő nem varázslatosan oldódik meg: Morzsi egy fogantyún tartja a súlyát, Zizi kis reteszt nyit, Márk a másik oldalon megemeli a levélalakú lapot. Lili alulról nézi a vezetősínt; egy kis kő akadt bele.
Mind megállnak. Lili kikotorja a kavicsot; a terelő ezután könnyen mozog. Zizi az új állásban rögzíti.
Morzsi visszateszi a fogantyút, ellenőrzi, hogy stabil. A csapat visszamegy Pöttyékhez, ugyanazon az úton. A szilánk helyén maradt; Pötty egy pillanatra sem vette fel.
Morzsi a fújtatóhoz áll, Márk a másodikhoz, Zizi a harmadikhoz. A dallam lassabban ismétlődik. Bogyó felismeri: három apró farokmozdulat, aztán megáll. Pötty nevetve figyel tovább.
Mély hang. Magas hang. Középső hang. Szünet.
Ezúttal a fény nem áll meg a hídnál, hanem a torony tetejéig fut. A harangok tisztán szólnak. A szélterelő megnyílt irányában puha légáram indul el.
A teljes kert válaszol: a szélkerék forogni kezd, a víz megemelkedik, az apró csatornák megtelnek. A lecsukott virágok kinyílnak. A lebegő szigetek finoman visszatérnek az eredeti magasságukra, a hidak stabilak maradnak. Senki sem zuhan, a térbeli mozgás lassú és áttekinthető.','A terelő nem varázslatosan oldódik meg: Morzsi egy fogantyún tartja a súlyát, Zizi kis reteszt nyit, Márk a másik oldalon megemeli a levélalakú lapot. Lili alulról nézi a vezetősínt; egy kis kő akadt bele.
Mind megállnak. Lili kikotorja a kavicsot; a terelő ezután könnyen mozog. Zizi az új állásban rögzíti.
Morzsi visszateszi a fogantyút, ellenőrzi, hogy stabil. A csapat visszamegy Pöttyékhez, ugyanazon az úton. A szilánk helyén maradt; Pötty egy pillanatra sem vette fel.
Morzsi a fújtatóhoz áll, Márk a másodikhoz, Zizi a harmadikhoz. A dallam lassabban ismétlődik. Bogyó felismeri: három apró farokmozdulat, aztán megáll. Pötty nevetve figyel tovább.
Mély hang. Magas hang. Középső hang. Szünet.
Ezúttal a fény nem áll meg a hídnál, hanem a torony tetejéig fut. A harangok tisztán szólnak. A szélterelő megnyílt irányában puha légáram indul el.
A teljes kert válaszol: a szélkerék forogni kezd, a víz megemelkedik, az apró csatornák megtelnek. A lecsukott virágok kinyílnak. A lebegő szigetek finoman visszatérnek az eredeti magasságukra, a hidak stabilak maradnak. Senki sem zuhan, a térbeli mozgás lassú és áttekinthető.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('8bb5238c-aebf-562f-95f9-4341cb5f7b7e','61e0de73-8206-4bf9-8ed7-f4132de7db50','9dbf3517-42a6-5b7c-85dd-ceda64f5772a','cec97482-1a11-4861-a09c-ad12c95476c5',1,1,'Álljatok meg egy kicsit.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('71b47e3e-f643-56ef-b31a-3bcd4dd35988','61e0de73-8206-4bf9-8ed7-f4132de7db50','9dbf3517-42a6-5b7c-85dd-ceda64f5772a','7786acf1-e358-4afd-9c7e-448230ada56e',2,2,'Ez volt az utolsó akadály. Most nem egyszerre erősebben kell. Hanem sorban újra.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('67d12ae7-e8f2-5ed1-92ec-7f9c33a31c5a','61e0de73-8206-4bf9-8ed7-f4132de7db50','9dbf3517-42a6-5b7c-85dd-ceda64f5772a','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',3,3,'Köszönöm, hogy szóltál, Lili.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('a0ae3697-0f8e-5de6-bbac-e230739ddb6e','61e0de73-8206-4bf9-8ed7-f4132de7db50','9dbf3517-42a6-5b7c-85dd-ceda64f5772a','cec97482-1a11-4861-a09c-ad12c95476c5',4,4,'Köszönöm, hogy megálltatok.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('a53e5c58-b51f-5b06-b8a6-d3bd933980ef','61e0de73-8206-4bf9-8ed7-f4132de7db50','9dbf3517-42a6-5b7c-85dd-ceda64f5772a','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',5,5,'Most!','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('f4ced559-80d6-576a-b1d1-9399450c8f6b','61e0de73-8206-4bf9-8ed7-f4132de7db50',16,16,'A KERT MEGKÖSZÖNI','A csapat biztonságos talajon áll. A szél egyetlen nagy kört ír le, majd gyengül. Morzsi visszasimítja a bundáját; most rögtön újra felborzolja egy kis fuvallat. Bogyó a levél után ugrik, aztán Pöttyhöz hozza.
Zizi a vízzel telt csatorna mellett kikapcsolva hagyja a mindenmérőt.
Márk visszaveszi a szilánkot a kendőben. A kapu tovább ragyog: most a kert szélkereke is táplálja a fénykört. A körkő közepén egy rövid térkép körvonala jelenik meg: sok kör, középen egy csillag. Egyetlen kör tartósan felvillan. A többi halvány.
A szilánk törött oldala mellett egy második, hiányzó rész körvonala látszik. Nem új szilánkot kapnak jutalmul; csak nyomot.
Morzsi felveszi a kosarat. Mind visszatérnek a kapusziget bokrához. Zizi leoldja a narancsszalagot, elteszi. Pötty megszámolja őket, Bogyót ezúttal maga mellett tartja.','A csapat biztonságos talajon áll. A szél egyetlen nagy kört ír le, majd gyengül. Morzsi visszasimítja a bundáját; most rögtön újra felborzolja egy kis fuvallat. Bogyó a levél után ugrik, aztán Pöttyhöz hozza.
Zizi a vízzel telt csatorna mellett kikapcsolva hagyja a mindenmérőt.
Márk visszaveszi a szilánkot a kendőben. A kapu tovább ragyog: most a kert szélkereke is táplálja a fénykört. A körkő közepén egy rövid térkép körvonala jelenik meg: sok kör, középen egy csillag. Egyetlen kör tartósan felvillan. A többi halvány.
A szilánk törött oldala mellett egy második, hiányzó rész körvonala látszik. Nem új szilánkot kapnak jutalmul; csak nyomot.
Morzsi felveszi a kosarat. Mind visszatérnek a kapusziget bokrához. Zizi leoldja a narancsszalagot, elteszi. Pötty megszámolja őket, Bogyót ezúttal maga mellett tartja.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('4d3b6367-69ec-5059-a821-7135139a7731','61e0de73-8206-4bf9-8ed7-f4132de7db50','f4ced559-80d6-576a-b1d1-9399450c8f6b','2eccce5e-599e-42bf-a58e-2068c34b312f',1,1,'Úgy látom, ez marad a mai frizurám.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('99926520-6c22-5525-b6ae-02aa7ec4871d','61e0de73-8206-4bf9-8ed7-f4132de7db50','f4ced559-80d6-576a-b1d1-9399450c8f6b','7786acf1-e358-4afd-9c7e-448230ada56e',2,2,'Ezt műszer nélkül is látom. Működik.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('79e0b3f8-a01f-5075-97ee-737c5eaadbf2','61e0de73-8206-4bf9-8ed7-f4132de7db50','f4ced559-80d6-576a-b1d1-9399450c8f6b','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',3,3,'Olyan, mintha a kapuhoz tartozna.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('78cc3f49-e8bd-57fd-bc08-ecf2f11d82c0','61e0de73-8206-4bf9-8ed7-f4132de7db50','f4ced559-80d6-576a-b1d1-9399450c8f6b','cec97482-1a11-4861-a09c-ad12c95476c5',4,4,'És nem csak ehhez a kerthez.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('b9f4b12e-ae6d-534e-8074-31f5d5f3a50f','61e0de73-8206-4bf9-8ed7-f4132de7db50','f4ced559-80d6-576a-b1d1-9399450c8f6b','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',5,5,'Hány darab lehet még?','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('2c5042b2-27c7-5789-b638-cdb73d17840d','61e0de73-8206-4bf9-8ed7-f4132de7db50','f4ced559-80d6-576a-b1d1-9399450c8f6b','7786acf1-e358-4afd-9c7e-448230ada56e',6,6,'Ezt most még a mindenmérő sem tudná.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('a92c5bd8-ddb1-5e64-9051-1cfab1bce788','61e0de73-8206-4bf9-8ed7-f4132de7db50','f4ced559-80d6-576a-b1d1-9399450c8f6b','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',7,7,'Hat. Most biztos.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('fba4250d-7c5d-576c-93fb-e4b21120ef68','61e0de73-8206-4bf9-8ed7-f4132de7db50','f4ced559-80d6-576a-b1d1-9399450c8f6b','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',8,8,'Hazamegyünk. De ezt nem felejtjük el.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('9fe040cc-0881-5701-888d-35ead54e6474','61e0de73-8206-4bf9-8ed7-f4132de7db50',17,17,'HAZA, EGYÜTT','A csapat ugyanabban a sorrendben lép vissza az erdőbe, Morzsi utolsóként. Lili ellenőrzi a hátizsákot, a kendőt, a csapatot. Márk kezében a szilánk. A kapun át még látszik a mozgó Szélkert; a fényfelület lassan bezárul. A kő türkiz jelei halványan megmaradnak.
Márk előveszi az uzsonnát. Morzsi nem kapja el, hanem az összes szereplőnek jut egy falat; Bogyónak külön kutyafalat a kosárból. Közben a szilánk a kendőn a fiú ölében marad.
Bogyó magára ismer a nevében, büszkén kihúzza magát. A levele, amit hozott, lecsúszik az orráról. Mind nevetnek.
A csapat az ösvényen Makkfalva felé indul. A nap már alacsonyabb, de még világos. Nincs indokolatlan éjszakai időugrás.','A csapat ugyanabban a sorrendben lép vissza az erdőbe, Morzsi utolsóként. Lili ellenőrzi a hátizsákot, a kendőt, a csapatot. Márk kezében a szilánk. A kapun át még látszik a mozgó Szélkert; a fényfelület lassan bezárul. A kő türkiz jelei halványan megmaradnak.
Márk előveszi az uzsonnát. Morzsi nem kapja el, hanem az összes szereplőnek jut egy falat; Bogyónak külön kutyafalat a kosárból. Közben a szilánk a kendőn a fiú ölében marad.
Bogyó magára ismer a nevében, büszkén kihúzza magát. A levele, amit hozott, lecsúszik az orráról. Mind nevetnek.
A csapat az ösvényen Makkfalva felé indul. A nap már alacsonyabb, de még világos. Nincs indokolatlan éjszakai időugrás.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('24f1ab63-c1e2-5b8b-81de-1da5322ba8e1','61e0de73-8206-4bf9-8ed7-f4132de7db50','9fe040cc-0881-5701-888d-35ead54e6474','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',1,1,'Most már köszöntünk, beszéltünk, és haza is jöttünk.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('38889253-51e7-56a4-adad-782ec64e5497','61e0de73-8206-4bf9-8ed7-f4132de7db50','9fe040cc-0881-5701-888d-35ead54e6474','2eccce5e-599e-42bf-a58e-2068c34b312f',2,2,'Akkor jöhet a túra másik fele.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('3a8c4427-a2c2-5645-ba62-20a5eae5894e','61e0de73-8206-4bf9-8ed7-f4132de7db50','9fe040cc-0881-5701-888d-35ead54e6474','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',3,3,'Majdnem úgy csináltam végig, mintha csak nekem lenne ötletem.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('02bb84bd-8e89-5095-a35c-ee7cc562c378','61e0de73-8206-4bf9-8ed7-f4132de7db50','9fe040cc-0881-5701-888d-35ead54e6474','7786acf1-e358-4afd-9c7e-448230ada56e',4,4,'Pedig nekem nagyon sok ötletem van. Néha túl sok.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('89f36e19-0d54-504e-8083-74e66ce72c5f','61e0de73-8206-4bf9-8ed7-f4132de7db50','9fe040cc-0881-5701-888d-35ead54e6474','cec97482-1a11-4861-a09c-ad12c95476c5',5,5,'Nekünk ma pont hat kellett.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('c90094a3-97a0-5f14-bafd-fc223bdc754c','61e0de73-8206-4bf9-8ed7-f4132de7db50','9fe040cc-0881-5701-888d-35ead54e6474','56d42a83-0d8d-4262-a66b-e6bd6de12aa7',6,6,'Az enyém az volt, hogy féljek egy kicsit, aztán mégis bemenjek.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('df5a9b77-32ef-5694-8eba-cd95c99a0a4d','61e0de73-8206-4bf9-8ed7-f4132de7db50','9fe040cc-0881-5701-888d-35ead54e6474','2eccce5e-599e-42bf-a58e-2068c34b312f',7,7,'Az enyém, hogy ne essen le a fedél.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into dialogue_lines(id,episode_id,scene_id,character_id,sequence_no,sequence,text,emotion,language,status) values ('80340fc7-c517-5440-977c-2918254b62b1','61e0de73-8206-4bf9-8ed7-f4132de7db50','9fe040cc-0881-5701-888d-35ead54e6474','9a4729ba-0b61-41e2-b3bc-2e65bea66eb0',8,8,'Bogyóé meg, hogy mutassa az utat.','neutral','hu','SCRIPT_DRAFT') on conflict(id) do nothing;
insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('057517fb-a8cd-5399-9d91-bc595177e156','61e0de73-8206-4bf9-8ed7-f4132de7db50',18,18,'NEM AZ EGYETLEN','Márk egyszer visszafordul az ösvényről. Felnyitja a kendőt. A szilánk törött oldala más irányba villan: a kapu egy eddig sötét felső körjelére. A jelben egy kicsi tollforma jelenik meg, aztán elhalványul.
Lili megáll mellette. Mindketten látják, nem csak a néző.
A szilánk három rövid fényt ad. Márk visszatakarja, csatlakoznak a többiekhez. A kamera a kapun marad: a tollforma halványan egyszer visszafénylik. Új célvilág még nincs megnyitva, nincs ismert eredet, nincs új beszélő gonosz vagy megmagyarázott Csillagkulcs.','Márk egyszer visszafordul az ösvényről. Felnyitja a kendőt. A szilánk törött oldala más irányba villan: a kapu egy eddig sötét felső körjelére. A jelben egy kicsi tollforma jelenik meg, aztán elhalványul.
Lili megáll mellette. Mindketten látják, nem csak a néző.
A szilánk három rövid fényt ad. Márk visszatakarja, csatlakoznak a többiekhez. A kamera a kapun marad: a tollforma halványan egyszer visszafénylik. Új célvilág még nincs megnyitva, nincs ismert eredet, nincs új beszélő gonosz vagy megmagyarázott Csillagkulcs.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
