insert into scenes(id,episode_id,scene_number,number,title,story_summary,summary) values ('a709440b-01bf-59da-bd43-7c2eb70e7a78','61e0de73-8206-4bf9-8ed7-f4132de7db50',19,19,'STÁBLISTA','Saját rövid zenei levezetés, hiteles stáblista. Nem használhatunk kitalált gyártói neveket, nem mondhatjuk elkészültnek a riget, amely még nincs meg. A végleges stáblista tényleges hozzájárulók és licencelt assetek alapján készül. Ez a tizenöt másodperc nem történeti kitöltés.','Saját rövid zenei levezetés, hiteles stáblista. Nem használhatunk kitalált gyártói neveket, nem mondhatjuk elkészültnek a riget, amely még nincs meg. A végleges stáblista tényleges hozzájárulók és licencelt assetek alapján készül. Ez a tizenöt másodperc nem történeti kitöltés.') on conflict(id) do update set scene_number=excluded.scene_number,number=excluded.number,title=excluded.title,story_summary=excluded.story_summary,summary=excluded.summary;
